function strength(pw) {
  let s = 0;
  if (pw.length >= 12) s += 2; else if (pw.length >= 8) s += 1;
  if (/[A-Z]/.test(pw) && /[a-z]/.test(pw)) s += 1;
  if (/[0-9]/.test(pw)) s += 1;
  if (/[^A-Za-z0-9]/.test(pw)) s += 1;
  return s >= 4 ? 'strong' : s >= 2 ? 'ok' : 'weak';
}
console.log('strength: ' + strength('Tr0ub4dor&3x'));

